const items = $input.all();

const fieldName =
  "USD | Accrual Basis | Management Accounts – Unaudited";

// Check if the input contains PDF/text content
const textInput = $input.first().json?.text;

let message;

if (textInput !== undefined && textInput !== null && textInput !== "") {
  // PDF/text input
  message = String(textInput);
} else {
  // Google Sheets / multiple items input
  const values = items
    .map(item => item.json?.[fieldName])
    .filter(
      value =>
        value !== undefined &&
        value !== null &&
        value !== ""
    );

  message = values
    .map(value => String(value))
    .join("\n");
}

// Return ONE n8n item
return [
  {
    json: {
      document: message
    }
  }
];

const input = $input.first();

const binary = input.binary || {};
const json = input.json || {};

let inputType = "API";
let message = "";

// --------------------------------------------------
// CHECK FOR FILE ATTACHMENT
// --------------------------------------------------

const binaryKeys = Object.keys(binary);

if (binaryKeys.length > 0) {

  const file = binary[binaryKeys[0]];

  const fileName = String(
    file.fileName || ""
  ).toLowerCase();

  const mimeType = String(
    file.mimeType || ""
  ).toLowerCase();

  // PDF
  if (
    fileName.endsWith(".pdf") ||
    mimeType === "application/pdf"
  ) {
    inputType = "PDF";
  }

  // Excel
  else if (
    fileName.endsWith(".xlsx") ||
    fileName.endsWith(".xls") ||
    mimeType === "application/vnd.ms-excel" ||
    mimeType ===
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
  ) {
    inputType = "Excel";
  }
}


// --------------------------------------------------
// GET API MESSAGE
// --------------------------------------------------

if (inputType === "API") {

  // body.Message
  if (json.body?.Message !== undefined) {
    message = String(json.body.Message);
  }

  // Message
  else if (json.Message !== undefined) {
    message = String(json.Message);
  }

  // body.message
  else if (json.body?.message !== undefined) {
    message = String(json.body.message);
  }

  // message
  else if (json.message !== undefined) {
    message = String(json.message);
  }
}


// --------------------------------------------------
// RETURN JSON + ORIGINAL BINARY
// --------------------------------------------------

return [
  {
    json: {
      input_type: String(inputType),
      message: String(message)
    },

    binary: binary
  }
];

const input = $input.first().json;

// Get AI output
let data = input.output;

// Parse JSON string
if (typeof data === "string") {
  data = JSON.parse(data);
}

// Find the statement where present = true
const statementEntry = Object.entries(data.statements || {})
  .find(([key, value]) => value?.present === true);

const statementType = statementEntry?.[0] || "";
const statement = statementEntry?.[1] || {};

const lineItems = Array.isArray(statement.line_items)
  ? statement.line_items
  : [];

// Create ONE output object
const output = {
  test_id: String(data.test_id ?? ""),
  document_id: String(data.document_id ?? ""),
  company_name: String(data.company_name ?? ""),
  reporting_period: String(data.reporting_period ?? ""),
  currency: String(data.currency ?? ""),
  document_status: String(data.document_status ?? ""),
  statement_type: String(statementType),
  statement_reconciled: String(statement.reconciled ?? ""),
  review_required: String(data.review_required ?? ""),
  review_reasons: Array.isArray(data.review_reasons)
    ? data.review_reasons.join(" | ")
    : String(data.review_reasons ?? "")
};

// Add EVERY line item as separate string fields
lineItems.forEach((item, index) => {

  const n = index + 1;

  output[`row_${n}_source_account`] =
    String(item.source_account ?? "");

  output[`row_${n}_amount`] =
    String(item.amount ?? "");

  output[`row_${n}_account_code`] =
    String(item.account_code ?? "");

  output[`row_${n}_account_name`] =
    String(item.account_name ?? "");

  output[`row_${n}_account_type`] =
    String(item.account_type ?? "");

  output[`row_${n}_confidence`] =
    String(item.confidence ?? "");

  output[`row_${n}_status`] =
    String(item.status ?? "");
});

// Return ONE n8n item
return [
  {
    json: output
  }
];

const input = $input.first().json;

// --------------------------------------------------
// 1. GET ORIGINAL DATA FROM DECISION NODE
// --------------------------------------------------

const previousNode = $('DecidesData_PDF_API_EXCEL').first().json;

const originalMessage = String(
  previousNode.message ?? ""
);

const inputType = String(
  previousNode.input_type ?? ""
).toUpperCase();


// --------------------------------------------------
// 2. DETERMINE SOURCE
// --------------------------------------------------

let source = "";

if (inputType === "API") {
  source = "Webhook";
}
else if (
  inputType === "PDF" ||
  inputType === "EXCEL"
) {
  source = "Email";
}
else {
  source = "Unknown";
}


// --------------------------------------------------
// 3. GENERATE RANDOM RUN ID
// --------------------------------------------------

const runId =
  "RUN-" +
  Date.now().toString(36).toUpperCase() +
  "-" +
  Math.random().toString(36).substring(2, 8).toUpperCase();


// --------------------------------------------------
// 4. FIND ALL ROWS
// --------------------------------------------------

const rowNumbers = Object.keys(input)
  .filter(key => /^row_\d+_source_account$/.test(key))
  .map(key => {
    const match = key.match(/^row_(\d+)_source_account$/);
    return Number(match[1]);
  })
  .sort((a, b) => a - b);


// --------------------------------------------------
// 5. COUNT ROWS
// --------------------------------------------------

const totalRows = rowNumbers.length;


// --------------------------------------------------
// 6. COUNT EXTRACTED + MAPPED ROWS
// --------------------------------------------------

let extractedRows = 0;
let mappedRows = 0;

for (const rowNumber of rowNumbers) {

  const sourceAccount = String(
    input[`row_${rowNumber}_source_account`] ?? ""
  ).trim();

  const status = String(
    input[`row_${rowNumber}_status`] ?? ""
  ).trim().toLowerCase();

  // Row counts as extracted if source account exists
  if (sourceAccount !== "") {
    extractedRows++;
  }

  // Row counts as mapped if status = mapped
  if (status === "mapped") {
    mappedRows++;
  }
}


// --------------------------------------------------
// 7. CREATE EXTRACTED ROWS STRING
// --------------------------------------------------

const extractedRowsString = rowNumbers
  .map(rowNumber => {

    const sourceAccount = String(
      input[`row_${rowNumber}_source_account`] ?? ""
    );

    const amount = String(
      input[`row_${rowNumber}_amount`] ?? ""
    );

    return `Row ${rowNumber}: ${sourceAccount} = ${amount}`;

  })
  .filter(row => !row.endsWith(" = "))
  .join(" | ");


// --------------------------------------------------
// 8. CREATE MAPPED ROWS STRING
// --------------------------------------------------

const mappedRowsString = rowNumbers
  .map(rowNumber => {

    const sourceAccount = String(
      input[`row_${rowNumber}_source_account`] ?? ""
    );

    const accountCode = String(
      input[`row_${rowNumber}_account_code`] ?? ""
    );

    const accountName = String(
      input[`row_${rowNumber}_account_name`] ?? ""
    );

    const accountType = String(
      input[`row_${rowNumber}_account_type`] ?? ""
    );

    const status = String(
      input[`row_${rowNumber}_status`] ?? ""
    ).toLowerCase();

    if (status !== "mapped") {
      return "";
    }

    return `Row ${rowNumber}: ${sourceAccount} -> ${accountCode} | ${accountName} | ${accountType}`;

  })
  .filter(row => row !== "")
  .join(" | ");


// --------------------------------------------------
// 9. RETURN ONE ITEM
// --------------------------------------------------

return [
  {
    json: {

      // Existing data
      ...input,

      // Original source data
      original_message: String(originalMessage),

      // Test run information
      run_id: String(runId),
      input_type: String(inputType),
      source: String(source),

      // Row statistics
      total_rows: String(totalRows),
      extracted_rows: String(extractedRows),
      mapped_rows: String(mappedRows),

      // Row strings
      extracted_rows_string: String(extractedRowsString),
      mapped_rows_string: String(mappedRowsString)

    }
  }
];

